const articles = [];

for (const item of $input.all()) {
  const results = item.json.results || [];

  for (const article of results) {
    articles.push({
      title: article.title,
      url: article.url,
      summary: (article.content || "").substring(0, 300),
    });
  }
}

return [
  {
    json: {
      articles,
    },
  },
];

// Split the 15-post array into one item per post, formatted + HTML-escaped for Telegram.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const order = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5 };
const posts = ($input.first().json.output && $input.first().json.output.posts) || [];

const sorted = [...posts].sort((a, b) => {
  const da = order[String(a.day || '').toLowerCase()] || 99;
  const db = order[String(b.day || '').toLowerCase()] || 99;
  return da - db || (Number(a.option) || 0) - (Number(b.option) || 0);
});

return sorted.map((p) => {
  const day = String(p.day || '').toUpperCase();
  const opt = p.option != null ? p.option : '?';
  const dev = Array.isArray(p.development) ? p.development : (p.development ? [p.development] : []);
  const devLines = dev.map((l) => {
    const t = String(l).trim();
    return /^(→|•|-|\*)/.test(t) ? esc(t) : '→ ' + esc(t);
  }).join('\n');
  const tags = Array.isArray(p.hashtags) ? p.hashtags.join(' ') : (p.hashtags || '');

  const message =
    `📅 <b>${esc(day)} — Option ${esc(opt)} of 3</b>\n\n` +
    `${esc(p.hook)}\n\n` +
    (devLines ? `${devLines}\n\n` : '') +
    `${esc(p.insight)}\n\n` +
    `${esc(p.question)}\n\n` +
    `${esc(tags)}\n\n` +
    `Source: ${esc(p.source_title)} ${esc(p.source_url)}`;

  return { json: { day, option: p.option, message } };
});
